import{z as l,x as B,o as e,c as p,q as A,j as o,D as E,d as t,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"高 NA 薄胶的转印","description":"","frontmatter":{"title":"高 NA 薄胶的转印","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-na-pattern-transfer.md","filePath":"litho/high-na-pattern-transfer.md","lastUpdated":1791063341000}'),h={name:"litho/high-na-pattern-transfer.md"};function d(D,a,m,C,u,c){const r=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=A('<h1 id="高-na-薄胶的转印" tabindex="-1">高 NA 薄胶的转印 <a class="header-anchor" href="#高-na-薄胶的转印" aria-label="Permalink to &quot;高 NA 薄胶的转印&quot;">​</a></h1><div class="epigraph"><p>成像层只剩十几纳米时，干法必须靠底层和硬掩模把深宽比接下去。转印失败的表现是倒线、掉选择比，不是曝光矩阵上 CD 还有窗。</p><footer>—— 对照 van Schoot 等 High-NA 成像；Levinson 多层硬掩模；金属氧化物胶的耐干法讨论</footer></div><p><a href="/litho/underlayer-secondary-electron">上一课</a>把潜像写到薄胶与界面电子。缺口是显影之后：浮雕太矮，直接当器件刻蚀掩模不够。本课钉高 NA 薄胶的图形转印。一层芯片要铺多少张 EUV 版，留给<a href="/litho/euv-layers-per-node">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/high-na-resist-budget">胶厚预算</a> 要求薄膜以满足焦深和倒塌；吸收课要求薄膜内仍有事件。显影后线高/线宽若仍想守约 2:1，高度只剩十纳米量级。前端刻蚀的深度远大于此，必须多层转印：成像层 → 底层/旋涂碳 → 含硅硬掩模 → 器件膜。金属氧化物胶自身耐干法，可以少一层，但仍要平面化和开口。</p><p>缺口是转印栈，不是再算一次 DOF。曝光窗开着、干法把线倒掉或 CD 漂移，整层仍报废。选择比、聚合物沉积、ALD/ALE 微调属于集成，但起点是光刻留下的矮浮雕。</p><p><span class="marginnote">术语翻译：SOC（旋涂碳）就是用旋涂的办法铺一层富碳有机膜，它不参与成像，只当&quot;分摊深度&quot;的牺牲中间层——上面接薄胶，下面接含硅硬掩模。</span></p><p><span class="marginnote">不要把 0.33 NA 上「三十纳米 CAR 直接挡刻」的流程拷到 EXE。High-NA 默认成像层是牺牲的记录介质。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈资格：每层选择比、开口偏置、线宽缩进、缺陷（桥、断）。轨道涂布与烘烤窗口与底层电子课绑定。干法：先打开薄胶下的有机层，再转硅硬掩模；等离子体对矮线的离子轰击和侧壁聚合物要重新开窗口。金属氧化物：配体解离后的金属氧网络当第一硬掩模，底层改管黏附与下一段。</p><p>计量：显影后 CD 不是终点，转印后 CD 和剖面才是。OPC 若只校准显影 SEM，会把刻蚀偏置当成光学偏置。</p><p><span class="marginnote">常见误区：显影后 SEM 量到 CD 合格就放行。实际上刻蚀还会把线宽再推偏几个纳米（刻蚀偏置），在 High-NA 更小的半节距下，这几个纳米占 CD 的比例远大于 0.33 NA——OPC 模型不把它吸收进去，整批线条就会系统性偏瘦或偏胖。</span></p><h3 id="倒塌发生在显影-墙却在转印" tabindex="-1">倒塌发生在显影，墙却在转印 <a class="header-anchor" href="#倒塌发生在显影-墙却在转印" aria-label="Permalink to &quot;倒塌发生在显影，墙却在转印&quot;">​</a></h3><p>深宽比判据看显影后湿态和干燥。转印等离子体再施加侧向离子和聚合物，矮线可能在干法里折断或变细。资格认证要覆盖显影→硬掩模开口全程，不能只过曝光矩阵。表面活性剂漂洗和超临界干燥是倒塌课的手段，High-NA 薄胶把它们从可选项变成栈的一部分。</p>',14)),(e(),o(s,null,{default:E(()=>[i(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E8%96%84%E6%88%90%E5%83%8F%E5%B1%82%22%5D%20--%3E%20UL%5B%22%E5%BA%95%E5%B1%82%20%2F%20SOC%22%5D%0A%20%20UL%20--%3E%20HM%5B%22%E5%90%AB%E7%A1%85%E6%88%96%E9%87%91%E5%B1%9E%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20HM%20--%3E%20DEV%5B%22%E5%99%A8%E4%BB%B6%E5%88%BB%E8%9A%80%22%5D%0A%20%20PR%20--%3E%20FAIL%5B%22%E5%80%92%E5%A1%8C%20%2F%20%E9%80%89%E6%AF%94%E4%B8%8D%E8%B6%B3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"离子刻蚀的选择比有限，掩模消耗量 \\(\\Delta t \\approx\\) 刻蚀深度 / 选择比。\\(\\Delta t\\) 大于胶厚则图形没。多层把深度分配给更耐的膜。随机孔缺失在转印中会被放大成硬掩模开孔失败，缺陷规格在成像层就要严于最终器件——转印有自己的 MEEF。High-NA 半节距更小，同样的侧壁角误差占 CD 比例更大。",-1)),(e(),o(s,null,{default:E(()=>[i(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%99%A8%E4%BB%B6%E5%88%BB%E8%9A%80%E6%B7%B1%E5%BA%A6%20500%20nm%22%5D%20--%3E%20B%5B%22%E7%AE%97%E6%8E%A9%E6%A8%A1%E6%B6%88%E8%80%97%20%CE%94t%20%3D%20%E6%B7%B1%E5%BA%A6%20%2F%20%E9%80%89%E6%8B%A9%E6%AF%94%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8D%95%E5%B1%82%E8%96%84%E8%83%B6%20%E9%80%89%E6%8B%A9%E6%AF%94%202%3A1%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%A6%81%E7%83%A7%E6%8E%89%20250%20nm%EF%BC%8C%E8%83%B6%E5%8F%AA%E6%9C%89%E5%8D%81%E5%87%A0%20nm%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%9B%BE%E5%BD%A2%E4%B8%AD%E9%80%94%E6%B6%88%E5%A4%B1%EF%BC%8C%E5%80%92%E7%BA%BF%E6%8A%A5%E5%BA%9F%22%5D%0A%20%20B%20--%3E%20F%5B%22%E5%A4%9A%E5%B1%82%E6%A0%88%20%E7%A1%85%E7%A1%AC%E6%8E%A9%E6%A8%A1%E9%80%89%E6%8B%A9%E6%AF%94%205%3A1%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%8F%AA%E8%80%97%20100%20nm%EF%BC%8CSOC%20%E6%89%9B%E5%89%A9%E4%BD%99%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%9B%BE%E5%BD%A2%E5%AE%8C%E6%95%B4%E8%BD%AC%E5%88%B0%E5%99%A8%E4%BB%B6%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">数字实例：要在硅里刻 500 nm，选择比 10:1 的硬掩模只需被吃掉 50 nm；若选择比掉到 2:1，就要烧掉 250 nm——比整层 High-NA 胶（约 15-30 nm）厚一个数量级。这就是&quot;一层胶直接挡刻&quot;在数学上必然输的原因。</span></p><p><span class="marginnote">为什么重要：转印栈里最耐刻的那层不是省材料的，是省报废的。把高选择比膜放在离器件最近的位置，每一层上游都只出&quot;自己的那份消耗&quot;，矮成像层才活得下来。</span></p><p><span class="marginnote">ALD/ALE 可以修剖面，补不回成像层已经缺失的孔。转印不是随机效应的保险箱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不统计某节点 EUV 用了几层金属、几层切，下一课才写层数与节点。不重写 FinFET/GAA 器件集成。转印偏置必须进 OPC 校准片，否则光学模型会背刻蚀的锅。出处：van Schoot High-NA；Levinson 硬掩模；euv-resist 金属胶耐刻；胶厚预算课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高 NA 薄胶默认走多层硬掩模转印，显影 CD 不是终点。</li><li>选择比和倒塌把成像层厚度与集成栈锁在一起。</li><li>下一课：这些转印步骤在整节点上对应多少张 EUV 版。</li><li>出处：van Schoot；Levinson；金属氧化物胶公开讨论。</li></ul>',7))])}const g=l(h,[["render",d]]);export{_ as __pageData,g as default};
